import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Simulate loading reels
        setTimeout(() => {
            setReels([
                {
                    id: 1,
                    title: 'New Summer Collection',
                    product: 'Summer Dress',
                    status: 'approved',
                    views: 1250,
                    likes: 342,
                    date: '2023-06-15'
                },
                {
                    id: 2,
                    title: 'Winter Sale Announcement',
                    product: 'Winter Coat',
                    status: 'pending',
                    views: 0,
                    likes: 0,
                    date: '2023-06-18'
                },
                {
                    id: 3,
                    title: 'New Arrival: Spring Shoes',
                    product: 'Spring Shoes',
                    status: 'approved',
                    views: 2100,
                    likes: 567,
                    date: '2023-06-10'
                }
            ]);
            setLoading(false);
        }, 500);
    }, []);

    const handleViewReel = async (reelId) => {
        // Navigate to the view page
        navigate(`/studio/seller/upload/${reelId}`);
    };

    const handleEditReel = (reelId) => {
        // Navigate to the edit page
        navigate(`/studio/seller/upload/${reelId}`);
    };

    const handleDeleteReel = async (reelId) => {
        // Confirm deletion
        if (window.confirm('Are you sure you want to delete this reel? This action cannot be undone.')) {
            try {
                // In a real app, you would make an API call to delete the reel
                // const response = await ApiService.deleteReel(reelId);
                // if (response.success) {
                    // Remove the reel from the list
                    setReels(reels.filter(reel => reel.id !== reelId));
                    toast.success('Reel deleted successfully!');
                // } else {
                //     toast.error('Failed to delete reel: ' + response.message);
                // }
            } catch (error) {
                console.error('Delete error:', error);
                toast.error('Failed to delete reel: ' + error.message);
            }
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        <Link to="/studio/seller/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Title</th>
                                            <th>Product</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>{reel.title}</td>
                                                <td>{reel.product}</td>
                                                <td>{getStatusBadge(reel.status)}</td>
                                                <td>{reel.views}</td>
                                                <td>{reel.likes}</td>
                                                <td>{reel.date}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info me-1"
                                                        onClick={() => handleViewReel(reel.id)}
                                                        title="View"
                                                    >
                                                        <i className="ri-eye-line"></i>
                                                    </button>
                                                    <button 
                                                        className="btn btn-sm btn-warning me-1"
                                                        onClick={() => handleEditReel(reel.id)}
                                                        title="Edit"
                                                    >
                                                        <i className="ri-edit-line"></i>
                                                    </button>
                                                    <button 
                                                        className="btn btn-sm btn-danger"
                                                        onClick={() => handleDeleteReel(reel.id)}
                                                        title="Delete"
                                                    >
                                                        <i className="ri-delete-bin-line"></i>
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
